import type { Plugin } from 'postcss';

/** Lower the CSS generated by Tailwind 3 for the legacy package, including syntax Vite does not lower. */
export function legacyCss(): Plugin {
  return {
    postcssPlugin: 'internal-assistant-chromium80-css',
    Declaration(declaration) {
      declaration.value = declaration.value
        .replace(/rgb\(\s*(\d+)\s+(\d+)\s+(\d+)\s*\//g, 'rgba($1,$2,$3,')
        .replace(/rgb\(\s*(\d+)\s+(\d+)\s+(\d+)\s*\)/g, 'rgb($1,$2,$3)');
      if (declaration.prop === 'inset') {
        const sides = declaration.value.trim().split(/\s+/);
        const [top, right = top, bottom = top, left = right] = sides;
        for (const [prop, value] of Object.entries({ top, right, bottom, left }))
          declaration.cloneBefore({ prop, value });
        declaration.remove();
      }
    },
    Rule(rule) {
      // Tailwind's class dark mode uses :is(.dark *); Chrome 80 needs the equivalent ancestor selector.
      rule.selector = rule.selector
        .split(',')
        .map(selector => {
          let next = selector;
          if (next.includes(':is(.dark *)')) next = `.dark ${next.replace(/:is\(\.dark \*\)/g, '')}`;
          next = next.replace(/:where\((:not\(\[hidden=(?:"until-found"|'until-found'|until-found)\]\))\)/g, '$1');
          next = next.replace(/:where\((\[[^\]]+\])\)/g, '$1');
          return next.replace(/:focus-visible/g, ':focus');
        })
        .join(',');
    },
  };
}
